import test from 'node:test';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {mkdtempSync, readFileSync, rmSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {planRedactions} from '../redaction-plan.js';

test('spec example: earliest start, then longest, then rule position', () => {
  assert.deepEqual(
    planRedactions('ababa', [
      {id: 'long', literal: 'aba', replacement: 'X'},
      {id: 'short', literal: 'ba', replacement: 'Y'},
    ]),
    {
      text: 'XY',
      edits: [
        {start: 0, end: 3, id: 'long'},
        {start: 3, end: 5, id: 'short'},
      ],
      originalBytes: 5,
      redactedBytes: 2,
    });
});

test('overlapping occurrences of one literal: earliest start wins, touching allowed', () => {
  const r = planRedactions('aaaa', [{id: 'o', literal: 'aa', replacement: 'B'}]);
  assert.equal(r.text, 'BB');
  assert.deepEqual(r.edits, [
    {start: 0, end: 2, id: 'o'},
    {start: 2, end: 4, id: 'o'},
  ]);
});

test('same start and same length: earlier rule position wins', () => {
  const r = planRedactions('xy', [
    {id: 'first', literal: 'xy', replacement: '1'},
    {id: 'second', literal: 'xy', replacement: '2'},
  ]);
  assert.equal(r.text, '1');
  assert.deepEqual(r.edits, [{start: 0, end: 2, id: 'first'}]);
});

test('empty text validates rules before matching', () => {
  assert.deepEqual(planRedactions('', [{id: 'a', literal: 'x', replacement: ''}]), {
    text: '',
    edits: [],
    originalBytes: 0,
    redactedBytes: 0,
  });
  assert.throws(
    () => planRedactions('', [{id: 'a', literal: 'x'}]),
    (err) => err instanceof Error && /replacement/.test(err.message),
  );
  assert.throws(
    () => planRedactions('', [{id: 'a', literal: 'x', replacement: 'y', id2: 1, ok: true}]),
  );
});

test('empty rules returns the original text untouched', () => {
  assert.deepEqual(planRedactions('hello', []), {
    text: 'hello',
    edits: [],
    originalBytes: 5,
    redactedBytes: 5,
  });
});

test('empty replacement removes text', () => {
  const r = planRedactions('abcabc', [{id: 'e', literal: 'a', replacement: ''}]);
  assert.equal(r.text, 'bcbc');
  assert.deepEqual(r.edits, [
    {start: 0, end: 1, id: 'e'},
    {start: 3, end: 4, id: 'e'},
  ]);
  assert.equal(r.redactedBytes, 4);
});

test('case sensitivity and literal (not regex) semantics', () => {
  assert.equal(
    planRedactions('A.B a.b (a.b)', [
      {id: 'dot', literal: 'a.b', replacement: 'X'},
      {id: 'paren', literal: '(a.b)', replacement: 'Y'},
    ]).text,
    'A.B X X',
  );
});

test('longer literal selected even when a shorter one starts earlier in the same window', () => {
  const r = planRedactions('xabcabc', [
    {id: 's', literal: 'abc', replacement: 'S'},
    {id: 'l', literal: 'abcabc', replacement: 'L'},
  ]);
  assert.equal(r.text, 'xL');
  assert.deepEqual(r.edits, [{start: 1, end: 7, id: 'l'}]);
});

test('replacement text is never reprocessed', () => {
  const r = planRedactions('ab', [
    {id: 'a', literal: 'a', replacement: 'bb'},
    {id: 'b', literal: 'bb', replacement: 'X'},
  ]);
  assert.equal(r.text, 'bbb');
  assert.deepEqual(r.edits, [{start: 0, end: 1, id: 'a'}]);
});

test('UTF-16 code-unit offsets and astral-plane bytes', () => {
  // '🦄' is 2 UTF-16 code units and 4 UTF-8 bytes.
  const r = planRedactions('x🦄x', [
    {id: 'uni', literal: '🦄', replacement: '?'},
  ]);
  assert.deepEqual(r.edits, [{start: 1, end: 3, id: 'uni'}]);
  assert.equal(r.text, 'x?x');
  assert.equal(r.originalBytes, 1 + 4 + 1);
  assert.equal(r.redactedBytes, 3);
});

test('surrogate pair literal matches whole pair only', () => {
  const r = planRedactions('ab🦄cd', [
    {id: 'lo', literal: '\ud83e', replacement: 'L'},
    {id: 'uni', literal: '🦄', replacement: 'U'},
  ]);
  assert.deepEqual(r.edits, [{start: 2, end: 4, id: 'uni'}]);
  assert.equal(r.text, 'abUcd');
});

test('opaque ids including __proto__ and unicode', () => {
  const r = planRedactions('pw pw', [
    {id: '__proto__', literal: 'pw', replacement: 'X'},
  ]);
  assert.deepEqual(r.edits, [
    {start: 0, end: 2, id: '__proto__'},
    {start: 3, end: 5, id: '__proto__'},
  ]);
  assert.equal(r.text, 'X X');
});

test('inputs are not mutated and frozen inputs work', () => {
  const rules = Object.freeze([
    Object.freeze({id: 'a', literal: 'ab', replacement: 'X'}),
  ]);
  const text = Object.freeze('abab');
  const before = JSON.stringify(rules);
  const r = planRedactions(text, rules);
  assert.equal(text, 'abab');
  assert.equal(JSON.stringify(rules), before);
  assert.equal(r.text, 'Xab');
  assert.deepEqual(r.edits, [{start: 0, end: 2, id: 'a'}]);
});

test('invalid inputs throw Error', () => {
  const bad = [
    [123, []],
    [null, []],
    [undefined, []],
    [true, []],
    ['abc', null],
    ['abc', 'abc'],
    ['abc', {}],
    ['abc', [null]],
    ['abc', [1]],
    ['abc', ['x']],
    ['abc', [{id: 1, literal: 'a', replacement: ''}]],
    ['abc', [{id: '', literal: 'a', replacement: ''}]],
    ['abc', [{id: 'a', literal: 5, replacement: ''}]],
    ['abc', [{id: 'a', literal: '', replacement: ''}]],
    ['abc', [{id: 'a', literal: 'x'}]],
    ['abc', [{id: 'a', literal: 'x', replacement: 0}]],
    ['abc', [{id: 'a', literal: 'x', replacement: null}]],
    ['abc', [{id: 'a', literal: 'x', replacement: 'y'}, {id: 'a', literal: 'z', replacement: ''}]],
    ['abc', [{id: 'a', literal: 'x', replacement: 'y'}, {id: 'b', literal: 'x', replacement: 'z'}, {id: 'a', literal: 'w', replacement: ''}]],
    // Sparse array is not dense.
    (() => {
      const sparse = [];
      sparse[0] = {id: 'a', literal: 'x', replacement: ''};
      sparse[2] = {id: 'b', literal: 'y', replacement: ''};
      return ['abc', sparse];
    })(),
  ];
  for (const [text, rules] of bad) {
    assert.throws(() => planRedactions(text, rules), (err) => err instanceof Error, `expected throw for ${JSON.stringify([text, rules])}`);
  }
});

test('CLI: success prints exactly the result plus newline, no stderr, exit 0', () => {
  const dir = mkdtempSync(join(tmpdir(), 'redact-plan-'));
  try {
    const file = join(dir, 'input.json');
    writeFileSync(file, JSON.stringify({text: 'ababa', rules: [
      {id: 'long', literal: 'aba', replacement: 'X'},
      {id: 'short', literal: 'ba', replacement: 'Y'},
    ], extra: 'ignored'}));
    const out = execFileSync('node', ['redaction-plan.js', file], {cwd: '/workspace', encoding: 'utf8'});
    assert.equal(out, `${JSON.stringify({
      text: 'XY',
      edits: [
        {start: 0, end: 3, id: 'long'},
        {start: 3, end: 5, id: 'short'},
      ],
      originalBytes: 5,
      redactedBytes: 2,
    })}\n`);
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
});

test('CLI: invalid arguments, files, JSON, and API input all exit 2 with stderr and no stdout', () => {
  const dir = mkdtempSync(join(tmpdir(), 'redact-plan-'));
  const cases = [];
  try {
    const run = (args, fileContent) => {
      const file = join(dir, `${cases.length}.json`);
      if (fileContent !== undefined) writeFileSync(file, fileContent);
      cases.push({args: args.map((a) => (a === 'FILE' ? file : a))});
      let code = 0;
      let stdout = '';
      let stderr = '';
      try {
        stdout = execFileSync('node', cases[cases.length - 1].args, {cwd: '/workspace', encoding: 'utf8'});
      } catch (err) {
        code = err.status ?? 1;
        stdout = String(err.stdout ?? '');
        stderr = String(err.stderr ?? '');
      }
      assert.equal(code, 2, `expected exit 2 for ${cases[cases.length - 1].args}`);
      assert.ok(stderr.length > 0, 'expected nonempty stderr');
      assert.equal(stdout, '', 'expected no stdout');
    };
    run([]);
    run(['FILE'], '{"text":"x","rules":[]}'); // nonexistent file
    run(['FILE', 'FILE'], '{"text":"x","rules":[]}'); // too many args
    run(['FILE'], 'not json');
    run(['FILE'], 'null');
    run(['FILE'], '[1,2]');
    run(['FILE'], '"str"');
    run(['FILE'], '17');
    run(['FILE'], '{"text":1,"rules":[]}');
    run(['FILE'], '{"text":"x","rules":{}}');
    run(['FILE'], '{"rules":[]}');
    run(['FILE'], '{"text":"x","rules":[{"id":"a","literal":"x"}]}');
    run(['FILE'], '{"text":"x","rules":[{"id":"a","literal":"x","replacement":""},{"id":"a","literal":"y","replacement":""}]}');
  } finally {
    rmSync(dir, {recursive: true, force: true});
  }
});

test('importing the module does not run the CLI', () => {
  const out = execFileSync('node', ['-e', `import('../redaction-plan.js').then(m => { console.log('exported:', typeof m.planRedactions); })`], {cwd: '/workspace', encoding: 'utf8'});
  assert.equal(out.trim(), 'exported: function');
});

