#!/usr/bin/env node
// Deterministic literal-redaction planner.
//
// planRedactions(text, rules) finds exact, case-sensitive occurrences of each
// rule's literal in the ORIGINAL text (offsets are UTF-16 code-unit indices,
// matching String.slice), selects nonoverlapping edits greedily
// (earliest start, then longest literal, then earliest rule position), and
// returns {text, edits, originalBytes, redactedBytes}. It never treats
// literals as regexes and never reprocesses replacement text.
import {readFileSync, realpathSync} from 'node:fs';
import {resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

const fail = (message) => {
  throw new Error(message);
};

const isPlainObject = (value) =>
  Object.prototype.toString.call(value) === '[object Object]' && value !== null;

const isString = (value) => typeof value === 'string';

function planRedactions(text, rules) {
  if (!isString(text)) fail('text must be a string');
  if (!Array.isArray(rules)) fail('rules must be an array');
  if (rules.length !== rules.filter((rule) => rule !== undefined).length) {
    fail('rules must be a dense array');
  }

  // Validate every rule before doing any matching, even when text is empty.
  const seenIds = new Set();
  for (const rule of rules) {
    if (!isPlainObject(rule)) {
      fail('each rule must be a non-null, non-array object');
    }
    const { id, literal, replacement } = rule;
    if (!isString(id) || id.length === 0) fail('rule id must be a nonempty string');
    if (!isString(literal) || literal.length === 0) {
      fail('rule literal must be a nonempty string');
    }
    if (!isString(replacement)) fail('rule replacement must be a string');
    if (seenIds.has(id)) fail(`duplicate rule id: ${id}`);
    seenIds.add(id);
  }

  const n = text.length;

  // Collect every occurrence (including overlapping) of every literal, in
  // rule-array order so rule position is the final tie-breaker.
  const groups = new Array(rules.length);
  let minLen = Infinity;
  for (let r = 0; r < rules.length; r++) {
    const literal = rules[r].literal;
    minLen = Math.min(minLen, literal.length);
    const group = [];
    for (let start = text.indexOf(literal); start !== -1; start = text.indexOf(literal, start + 1)) {
      group.push(start);
    }
    groups[r] = group;
  }

  // Greedy selection: earliest start, then longest literal, then earlier
  // rule position. A selected edit blocks only matches starting before its
  // end, so touching edits are allowed and rejected starts simply fall out
  // of the window. Every group is sorted, and each rule contributes only its
  // earliest unblocked start (all of its starts are valid by construction).
  const selected = [];
  let pos = 0;
  while (pos <= n - minLen) {
    let bestStart = Infinity;
    let bestLen = 0;
    let bestRule = Infinity;
    for (let r = 0; r < rules.length; r++) {
      const group = groups[r];
      const len = rules[r].literal.length;
      let i = 0;
      while (i < group.length && group[i] < pos) i++;
      if (i === group.length) continue;
      const start = group[i];
      if (start < bestStart || (start === bestStart && len > bestLen)) {
        bestStart = start;
        bestLen = len;
        bestRule = r;
      }
    }
    if (bestRule === Infinity) break;
    selected.push({ start: bestStart, end: bestStart + bestLen, rule: bestRule });
    pos = bestStart + bestLen;
  }

  // Assemble the result, preserving every unselected source character.
  let out = '';
  let cursor = 0;
  const edits = [];
  for (const sel of selected) {
    out += text.slice(cursor, sel.start);
    out += rules[sel.rule].replacement;
    edits.push({ start: sel.start, end: sel.end, id: rules[sel.rule].id });
    cursor = sel.end;
  }
  out += text.slice(cursor);

  return {
    text: out,
    edits,
    originalBytes: Buffer.byteLength(text, 'utf8'),
    redactedBytes: Buffer.byteLength(out, 'utf8'),
  };
}

export { planRedactions };

// CLI: node redaction-plan.js INPUT_JSON_FILE
// Runs only when this file is the main module, so importing never runs the CLI.
function isMainModule() {
  if (!process.argv[1]) return false;
  try {
    return realpathSync(resolve(process.argv[1])) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}
if (isMainModule()) {
  const cliFail = (message) => {
    process.stderr.write(`${message}\n`);
    process.exit(2);
  };
  if (process.argv.length !== 3) {
    cliFail('usage: node redaction-plan.js INPUT_JSON_FILE (exactly one argument required)');
  }
  let raw;
  try {
    raw = readFileSync(process.argv[2], 'utf8');
  } catch (err) {
    cliFail(`cannot read input file: ${err.message}`);
  }
  let payload;
  try {
    payload = JSON.parse(raw);
  } catch (err) {
    cliFail(`invalid JSON: ${err.message}`);
  }
  if (!isPlainObject(payload)) {
    cliFail('input JSON must be a non-null, non-array object');
  }
  try {
    const result = planRedactions(payload.text, payload.rules);
    process.stdout.write(`${JSON.stringify(result)}\n`);
    process.exit(0);
  } catch (err) {
    cliFail(`invalid input: ${err.message}`);
  }
}

